// And groups predicates with the AND operator between them.
func And(predicates ...predicate.PostIssue) predicate.PostIssue {
	return predicate.PostIssue(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.PostIssue) predicate.PostIssue {
	return predicate.PostIssue(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.PostIssue) predicate.PostIssue {
	return predicate.PostIssue(sql.NotPredicates(p))
}
